from slotplan.intervals_overlap import intervals_overlap

def expand_weekly(days: Iterable[int], start: int, end: int, count: int, blackouts: Iterable[Tuple[int, int]] = ()) -> List[Tuple[int, int, int]]:
    if count < 0: raise ValueError()
    if end <= start: raise ValueError()

    day_list = list(days)
    if not day_list: raise ValueError()
    for d in day_list:
        if not (0 <= d <= 6): raise ValueError()

    unique_days = sorted(set(day_list))
    blackouts_list = list(blackouts)

    candidates = []
    week = 0
    while len(candidates) < count:
        for d in unique_days:
            if len(candidates) < count:
                candidates.append((week * 7 + d, start, end))
        week += 1

    results = []
